const purgarEnvios = `-- name: PurgarEnvios :execrows
DELETE FROM notificaciones.envios WHERE created_at < $1
`

func (q *Queries) PurgarEnvios(ctx context.Context, antes time.Time) (int64, error) {
	result, err := q.db.Exec(ctx, purgarEnvios, antes)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const quitarTokenDeOtros = `-- name: QuitarTokenDeOtros :many

DELETE FROM notificaciones.dispositivos
WHERE token_hash = $1 AND usuario_id <> $2
RETURNING id, usuario_id, empresa_id, sesion_id, token_api_id, plataforma, token, token_hash, token_fin, app_version, ultimo_envio_en, created_at, updated_at
`

type QuitarTokenDeOtrosParams struct {
	TokenHash []byte
	UsuarioID int64
}

// Dispositivos -----------------------------------------------------------------------------------
// El token pasó a otro usuario (el teléfono cambió de manos): se quita a los demás.
func (q *Queries) QuitarTokenDeOtros(ctx context.Context, arg QuitarTokenDeOtrosParams) ([]NotificacionesDispositivo, error) {
	rows, err := q.db.Query(ctx, quitarTokenDeOtros, arg.TokenHash, arg.UsuarioID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []NotificacionesDispositivo
	for rows.Next() {
		var i NotificacionesDispositivo
		if err := rows.Scan(
			&i.ID,
			&i.UsuarioID,
			&i.EmpresaID,
			&i.SesionID,
			&i.TokenApiID,
			&i.Plataforma,
			&i.Token,
			&i.TokenHash,
			&i.TokenFin,
			&i.AppVersion,
			&i.UltimoEnvioEn,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
